// Recuperacao pelo e-mail da compra: manda TODOS os acessos ligados a esse e-mail (compras e renovacoes, cada login com a validade atual).
// So vai para o proprio e-mail cadastrado, entao nao precisa da data da compra.
const email = limpaEmail(P.email);
const vazio = (m) => { const cod = /invalido/.test(m) ? 'email_invalido' : /nenhuma compra/.test(m) ? 'nao_encontrado' : 'nenhum_ativo'; return [{ json: { ok: false, motivo: m, resposta: { success: false, motivo: cod, enviado_para: email } } }]; };
if (!email.includes('@')) return vazio('e-mail invalido');
const pags = linhas('Recuperar: ler pagamentos');
const vendas = $('Recuperar: vendas da Liss').all().map(i => i.json);
const token = segredo('painel_token_publico', 'Recuperar: segredos');
const valida = s => s && !String(s).startsWith('(');
const doEmail = pags.filter(x => String(x.email || '').trim().toLowerCase() === email && ['venda', 'renovacao'].includes(String(x.tipo || '').trim().toLowerCase()));
// logins desse e-mail (o mais recente primeiro), vindos da planilha e das vendas da Liss
const users = [];
for (const x of doEmail.slice().reverse()) { const u = limpaUser(x.usuario_entregue); if (u && !users.includes(u)) users.push(u); }
for (const v of vendas.slice().reverse()) if (String(v.email || '').toLowerCase() === email && v.usuario && !users.includes(v.usuario)) users.push(v.usuario);
if (!users.length) return vazio('nenhuma compra com esse e-mail');
const http = async (o) => { try { return await this.helpers.httpRequest(Object.assign({ json: true, timeout: 25000, returnFullResponse: true, ignoreHttpStatusErrors: true }, o)); } catch (e) { return { statusCode: 0, body: {} }; } };
const contas = [];
for (const u of users.slice(0, 10)) {
  let senha = '';
  const v = vendas.slice().reverse().find(x => x.usuario === u && valida(x.senha)); if (v) senha = v.senha;
  if (!senha && token) {
    // compra do sistema antigo: o painel devolve a senha pelo pagamento (tenta a compra original primeiro)
    const linhasU = pags.filter(x => limpaUser(x.usuario_entregue) === u && /^[0-9]+$/.test(String(x.payment_id || '').trim()))
      .sort((p, q) => (String(p.tipo) === 'venda' ? -1 : 1) - (String(q.tipo) === 'venda' ? -1 : 1));
    for (const x of linhasU) {
      const r = await http({ method: 'GET', url: 'https://painel.netliss.shop/api/public/payment/' + String(x.payment_id).trim() + '/status', headers: { 'X-Public-Api-Token': token } });
      const a = (r.body && (r.body.account || (r.body.data && r.body.data.account))) || {};
      if (a.username === u && valida(a.password)) { senha = a.password; break; }
      if (!a.username && a.password && valida(a.password)) { senha = a.password; break; }
    }
  }
  let expira = '', vencido = false, existe = true;
  if (token) {
    const r = await http({ method: 'POST', url: 'https://painel.netliss.shop/api/public/renewal/search', headers: { 'X-Public-Api-Token': token }, body: { identifier: u } });
    const a = (r.body && (r.body.account || (r.body.data && r.body.data.account))) || null;
    if (a && a.expires_at) { const d = new Date(String(a.expires_at).replace(' ', 'T') + (/Z|[+-]\d\d:?\d\d$/.test(String(a.expires_at)) ? '' : '-03:00'));
      expira = isNaN(d) ? String(a.expires_at) : d.toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }).replace(',', '').slice(0, 16); vencido = !!a.is_expired || (!isNaN(d) && d < new Date()); }
    else if (r.statusCode === 404 || (r.body && r.body.success === false)) existe = false;
  }
  if (existe) contas.push({ usuario: u, senha, expira, vencido });
}
// decisao do dono: manda SO os acessos ativos (vencido nao vai no e-mail)
const ativos = contas.filter(c => !c.vencido);
if (!ativos.length) return [{ json: { ok: false, motivo: 'nenhum acesso ativo', resposta: { success: false, motivo: 'nenhum_ativo', enviado_para: email } } }];
contas.length = 0; ativos.forEach(c => contas.push(c));
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const caixa = 'font-family: monospace; font-size:20px; color:#12141a; margin-top:6px; padding:10px 14px; background:#f5f6f8; border-radius:8px; user-select:all; -webkit-user-select:all;';
const blocos = contas.map((c, i) => '<div style="border:1px solid #e7e9ee; border-radius:10px; margin:0 0 16px;">'
  + (contas.length > 1 ? '<div style="padding:10px 18px; background:#f6fbe9; font-size:12px; letter-spacing:1.2px; color:#4d6b12;">ACESSO ' + String(i + 1).padStart(2, '0') + '</div>' : '')
  + '<div style="padding:14px 18px; border-bottom:1px solid #f0f1f4;"><span style="font-size:12px; color:#8b93a1;">USUÁRIO</span><div style="' + caixa + '">' + esc(c.usuario) + '</div></div>'
  + '<div style="padding:14px 18px; border-bottom:1px solid #f0f1f4;"><span style="font-size:12px; color:#8b93a1;">SENHA</span>' + (c.senha ? '<div style="' + caixa + '">' + esc(c.senha) + '</div>' : '<div style="font-size:14px; color:#3d4350; margin-top:6px;">Não consegui localizar a senha deste usuário. Fale com a Liss no site que a nossa equipe envia para você.</div>') + '</div>'
  + '<div style="padding:14px 18px;"><span style="font-size:12px; color:#8b93a1;">' + (c.vencido ? 'VENCEU EM' : 'VÁLIDO ATÉ') + '</span><div style="font-size:15px; color:' + (c.vencido ? '#a33' : '#12141a') + '; margin-top:5px;">' + esc(c.expira || 'consulte no aplicativo') + '</div></div></div>').join('');
const algumVencido = contas.some(c => c.vencido);
const html = '<div style="font-family: -apple-system, Segoe UI, Roboto, Arial, sans-serif; background:#f5f6f8; padding:32px 16px;"><div style="max-width:480px; margin:0 auto;"><div style="background:#ffffff; border:1px solid #e7e9ee; border-radius:14px; overflow:hidden;"><div style="background:#000000; padding:26px 20px; text-align:center;"><img src="https://i.imgur.com/9WE3IIp.png" width="150" alt="Netliss"></div><div style="height:3px; background:#c4f82a;"></div><div style="padding:30px 28px;">'
  + '<p style="margin:0 0 4px; font-size:12px; letter-spacing:1.6px; color:#8b93a1;">RECUPERAÇÃO DE ACESSO</p>'
  + '<p style="margin:0 0 6px; font-size:21px; color:#12141a; font-weight:600;">' + (contas.length > 1 ? 'Aqui estão os seus ' + String(contas.length).padStart(2, '0') + ' acessos.' : 'Aqui está o seu acesso.') + '</p>'
  + '<p style="margin:0 0 20px; font-size:14.5px; color:#3d4350; line-height:1.6;">' + (contas.length > 1 ? 'Você tem mais de um acesso ativo comprado com este e-mail. ' : '') + 'Toque e segure sobre o usuário ou a senha até aparecer a opção de copiar. Depois é só colar no aplicativo.</p>'
  + blocos
  + '<div style="text-align:center;"><a href="https://netliss.com" style="display:inline-block; background:#12141a; color:#ffffff; text-decoration:none; font-size:15px; font-weight:600; padding:14px 30px; border-radius:10px;">Preciso de ajuda</a></div>'
  + '<div style="border-top:1px solid #f0f1f4; padding-top:18px; margin-top:26px;"><p style="margin:0; font-size:13px; color:#8b93a1; line-height:1.6;">Você recebeu este e-mail porque alguém pediu a recuperação de acesso no chat do nosso site usando este endereço. Se não foi você, pode ignorar: os dados chegam somente aqui.</p></div>'
  + '</div></div><div style="text-align:center; padding-top:20px;"><p style="margin:0; font-size:12px; color:#9aa1ad;">netliss.com &middot; internet ilimitada para celular</p></div></div></div>';
return [{ json: { ok: true, email, html, resumo: contas.map(c => c.usuario + (c.vencido ? ' (vencido)' : ' (ativo)') + (c.senha ? '' : ' sem senha')), resposta: { success: true, enviado_para: email, acessos: contas.length, ativos: contas.filter(c => !c.vencido).length } } }];

