const v = linhas('Venda: visitante')[0] || {};
const tipo = origemDe(v), orig = limpaId(v.origem), volta = limpaId(v.ultima_origem), camp = limpaTxt(v.campanha), afil = limpaId(v.ref_indicador);
const renov = String(P.renovar || '').length > 0, pix = P.metodo === 'pix';
