const nome = limpaTxt(String(P.nome || '').replace(/[^A-Za-zÀ-ÿ '.-]/g, '') || v.nome).slice(0, 60);
const linha = { payment_id: String(P.payment_id).replace(/[^0-9]/g, ''), id_netliss: limpaId(P.id_netliss), tipo: renov ? 'renovacao' : 'venda', plano: limpaTxt(P.plano), plan_id: 'liss',
