  usuario_entregue: limpaUser(P.usuario), gclid: limpaId(v.gclid), email: limpaEmail(P.email), ref: limpaId(P.ref), entregue_em: agora(),
  canal: tipo, operadora: op, modalidade: mod, nome, origem: orig, ultima_origem: volta };
const modTxt = mod ? ({ PRE: 'Pré-pago', POS: 'Pós-pago' }[mod.toUpperCase()] || mod) : 'modalidade não informada';
